import{_ as a,o as t,c as n,a4 as e}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"Claude Code 记忆机制：文件化索引 + 按需加载","description":"","frontmatter":{"title":"Claude Code 记忆机制：文件化索引 + 按需加载","date":"2026-08-24T00:00:00.000Z"},"headers":[],"relativePath":"ai-agent/case-studies/claude-code-memory.md","filePath":"ai-agent/case-studies/claude-code-memory.md"}'),i={name:"ai-agent/case-studies/claude-code-memory.md"};function o(l,s,r,d,p,h){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="claude-code-记忆机制-文件化索引-按需加载" tabindex="-1">Claude Code 记忆机制：文件化索引 + 按需加载 <a class="header-anchor" href="#claude-code-记忆机制-文件化索引-按需加载" aria-label="Permalink to &quot;Claude Code 记忆机制：文件化索引 + 按需加载&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">一句话说清</p><p>Claude Code 用两套互补的 markdown 记忆机制解决&quot;跨会话失忆&quot;：<strong>CLAUDE.md（人工指令）</strong> + <strong>Auto Memory（自动笔记）</strong>，核心设计是&quot;<strong>索引常驻 + 内容按需</strong>&quot;——不依赖数据库和向量库，纯文件系统搞定。这套模式是给 AI Agent 搭项目级记忆系统的最简可行方案。</p></div><h2 id="为什么需要记忆系统" tabindex="-1">为什么需要记忆系统 <a class="header-anchor" href="#为什么需要记忆系统" aria-label="Permalink to &quot;为什么需要记忆系统&quot;">​</a></h2><p>LLM 是无状态的：<strong>每轮对话都是一张白纸</strong>。上次会话里告诉它的&quot;项目用 TypeScript strict 模式&quot;、&quot;提交信息用 conventional commits&quot;，关掉终端就全没了。</p><ul><li>个人场景：每次开会话都要重复同样的规范，浪费</li><li>团队场景：你花了半小时教会 Claude 项目约定，这些约定只存在那一轮对话里，换个人一切从头</li></ul><p>Claude Code 用文件系统解决了这个问题。</p><h2 id="两套互补的记忆机制" tabindex="-1">两套互补的记忆机制 <a class="header-anchor" href="#两套互补的记忆机制" aria-label="Permalink to &quot;两套互补的记忆机制&quot;">​</a></h2><h3 id="_1-claude-md-你写给-claude-的指令" tabindex="-1">1. CLAUDE.md：你写给 Claude 的指令 <a class="header-anchor" href="#_1-claude-md-你写给-claude-的指令" aria-label="Permalink to &quot;1. CLAUDE.md：你写给 Claude 的指令&quot;">​</a></h3><p>人工维护、可提交 Git、团队共享。有<strong>四个层级</strong>，会话启动时自动加载：</p><table tabindex="0"><thead><tr><th>层级</th><th>路径</th><th>用途</th></tr></thead><tbody><tr><td>全局</td><td><code>~/.claude/CLAUDE.md</code></td><td>你的通用偏好（用中文回复、函数式风格）</td></tr><tr><td>项目</td><td><code>./CLAUDE.md</code></td><td>项目规范、架构、技术栈约定（跟 Git 走，团队共享）</td></tr><tr><td>个人本地</td><td><code>./CLAUDE.local.md</code></td><td>个人偏好（<code>.gitignore</code> 掉，不共享）</td></tr><tr><td>模块化规则</td><td><code>.claude/rules/*.md</code></td><td>分主题规则，<strong>支持 glob 条件加载</strong></td></tr></tbody></table><p>加载方式：会话启动时从当前目录<strong>向上遍历</strong>，加载沿途所有 CLAUDE.md（monorepo 子包进入即生效）。上下文压缩后还会从磁盘<strong>重新读取注入</strong>——写在 CLAUDE.md 里的规则不会丢，只存在对话里的才会丢。</p><p><strong><code>.claude/rules/</code> 是精华</strong>：规则文件 frontmatter 写 <code>paths</code> 字段即可按需加载：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - src/api/**/*.ts</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>## API 规范</span></span>
<span class="line"><span>- 所有接口必须有入参校验</span></span></code></pre></div><p>这条规则只在 Claude 处理 <code>src/api/</code> 下的文件时加载——编辑前端组件时不出现，不浪费上下文。这是&quot;按需加载&quot;的第一个落地形态，触发条件是<strong>文件路径 glob</strong>。</p><h3 id="_2-auto-memory-claude-自己记的笔记" tabindex="-1">2. Auto Memory：Claude 自己记的笔记 <a class="header-anchor" href="#_2-auto-memory-claude-自己记的笔记" aria-label="Permalink to &quot;2. Auto Memory：Claude 自己记的笔记&quot;">​</a></h3><p>无需手动操作，工作过程中自动积累：</p><ul><li><strong>什么会被记住</strong>：你的纠正（&quot;用 X 不要用 Y&quot;）、明确指令（&quot;记住以后都用 bun&quot;）、反复出现的模式、项目关键信息</li><li><strong>存储位置</strong>：<code>~/.claude/projects/&lt;项目&gt;/memory/</code>，个人私有，不进 Git</li><li><strong>触发方式</strong>：识别&quot;记住&quot;、&quot;别忘了&quot;、&quot;remember&quot;、&quot;don&#39;t forget&quot;等关键词时主动写入</li></ul><p><strong>存储结构</strong>——主文件常驻，主题文件按需：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/projects/&lt;项目&gt;/memory/</span></span>
<span class="line"><span>  MEMORY.md           # 主记忆，每次会话启动时加载（≤200 行）</span></span>
<span class="line"><span>  debugging.md        # 主题文件，需要时按需读取</span></span>
<span class="line"><span>  patterns.md</span></span>
<span class="line"><span>  api-conventions.md</span></span></code></pre></div><p>关键设计：<strong>MEMORY.md 常驻注入，主题文件按需读取</strong>——详细经验存子文件不占上下文，需要时才翻出来。</p><h3 id="_3-memory-命令" tabindex="-1">3. /memory 命令 <a class="header-anchor" href="#_3-memory-命令" aria-label="Permalink to &quot;3. /memory 命令&quot;">​</a></h3><p>查看当前会话加载了哪些记忆文件、切换 Auto Memory 开关、直接打开记忆目录编辑。回答一个基本问题：<strong>Claude 现在记住了什么？</strong></p><h2 id="核心设计-索引常驻-内容按需" tabindex="-1">核心设计：索引常驻 + 内容按需 <a class="header-anchor" href="#核心设计-索引常驻-内容按需" aria-label="Permalink to &quot;核心设计：索引常驻 + 内容按需&quot;">​</a></h2><p>两套机制共用一个模式——<strong>两段式加载</strong>：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Resident[&quot;常驻层（启动注入，占小 token）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A[&quot;CLAUDE.md&lt;br/&gt;项目规则&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B[&quot;MEMORY.md&lt;br/&gt;自动记忆索引 ≤200 行&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C[&quot;rules/*.md&lt;br/&gt;无 paths 的全局规则&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph OnDemand[&quot;按需层（触发时读取，不占常驻）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D[&quot;rules/*.md&lt;br/&gt;带 paths 按文件路径加载&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        E[&quot;debugging.md&lt;br/&gt;主题记忆文件&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F[&quot;LLM 处理任务&quot;] --&gt;|&quot;路径匹配&quot;| D</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|&quot;判断需要回忆&quot;| E</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|&quot;常驻上下文&quot;| G[&quot;遵守规则行事&quot;]</span></span></code></pre></div><p>与 <a href="/knowledge/ai-agent/prompt-engineering/skills.html">Skill 的两段式加载</a> 是同一思路：<strong>元数据/索引常驻 + 正文按需注入</strong>。Skill 的触发条件是 <code>description</code> 语义匹配，rules 的触发条件是路径 glob，Auto Memory 主题文件的触发条件是 LLM 自主判断。</p><h2 id="可靠性边界-依赖-llm-自觉按需加载" tabindex="-1">可靠性边界：依赖 LLM&quot;自觉按需加载&quot; <a class="header-anchor" href="#可靠性边界-依赖-llm-自觉按需加载" aria-label="Permalink to &quot;可靠性边界：依赖 LLM&quot;自觉按需加载&quot;&quot;">​</a></h2><p>这个模式的决策权交给了 LLM，而 LLM 的自主性不可靠，有两个失效模式：</p><ol><li><strong>不触发</strong>：长会话、任务复杂时，LLM 可能&quot;忘了&quot;去查索引——提示词只能要求，无法强制（这正是 <a href="/knowledge/ai-agent/harness-engineering/core-concepts.html">Harness 工程</a> 的核心痛点）</li><li><strong>编造</strong>：LLM 可能凭索引的印象或想象回答，而不去读真实文件内容——索引里一行&quot;有 auth 规范，见 auth.md&quot;，它可能不读就开写</li></ol><p>Claude Code 的缓解手段是&quot;<strong>200 行法则</strong>&quot;：CLAUDE.md 和 MEMORY.md 都限制在 200 行内。索引一旦膨胀，LLM 的注意力被稀释，遵守度下降；更糟的是索引本身变成&quot;该按需加载的大文件&quot;，违背设计初衷。</p><h2 id="实践指南-用-markdown-搭项目级记忆系统" tabindex="-1">实践指南：用 markdown 搭项目级记忆系统 <a class="header-anchor" href="#实践指南-用-markdown-搭项目级记忆系统" aria-label="Permalink to &quot;实践指南：用 markdown 搭项目级记忆系统&quot;">​</a></h2><p>如果你要自己搭一个项目级记忆系统，最简方案就是 Claude Code 这套模式的直接复刻：</p><blockquote><p><strong>用 markdown 维护一个知识库目录，在根目录暴露索引文件，把索引暴露给 LLM，依赖它的按需加载。</strong></p></blockquote><p>这是<strong>最简单</strong>的可行方案：零数据库、零向量库、零服务，纯文件 + 一个索引，人和 AI 共享同一套可 git 版本管理的资产。</p><h3 id="索引文件模板" tabindex="-1">索引文件模板 <a class="header-anchor" href="#索引文件模板" aria-label="Permalink to &quot;索引文件模板&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 项目知识库索引（常驻段：≤200 行，核心规则直接内联）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 硬性规则（必须遵守，不必读文件）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 所有新文件必须使用 TypeScript strict 模式</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 提交信息遵循 conventional commits</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 禁止修改 legacy/ 目录下任何文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 知识文件目录（按需段：触发时读对应文件）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 文件 | 内容 | 适用场景 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|------|------|---------|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`kb/api-conventions.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | API 入参校验、错误码、响应格式 | 处理 src/api/ 相关任务 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`kb/auth-flow.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 认证流程、token 机制 | 涉及登录/鉴权 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`kb/testing.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | 测试命令、覆盖率要求 | 任何改代码后的验证 |</span></span></code></pre></div><h3 id="四个默认动作-覆盖大部分风险" tabindex="-1">四个默认动作，覆盖大部分风险 <a class="header-anchor" href="#四个默认动作-覆盖大部分风险" aria-label="Permalink to &quot;四个默认动作，覆盖大部分风险&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手段</th><th>做法</th><th>成本</th></tr></thead><tbody><tr><td><strong>索引小型化</strong></td><td>索引 ≤200 行，只放核心规则 + 文件清单</td><td>零</td></tr><tr><td><strong>关键知识内联</strong></td><td>最高频的规则直接写进索引，而不是只留链接</td><td>零</td></tr><tr><td><strong>适用场景标注</strong></td><td>每篇知识文件顶部写 <code>## 适用场景</code>，给 LLM 判断&quot;要不要读&quot;的信号</td><td>零</td></tr><tr><td><strong>命令式规则</strong></td><td>写&quot;必须&quot;指令而非描述句（&quot;必须用 strict 模式&quot; ≠ &quot;项目使用 TS&quot;）</td><td>零</td></tr></tbody></table><h3 id="规模阈值-什么时候该升级" tabindex="-1">规模阈值：什么时候该升级 <a class="header-anchor" href="#规模阈值-什么时候该升级" aria-label="Permalink to &quot;规模阈值：什么时候该升级&quot;">​</a></h3><p>纯索引方案在<strong>几十个文件、每篇几百行</strong>以内是最优解。再往上：</p><ul><li><strong>索引膨胀</strong>（&gt;200 行法则失效）→ 轻量升级：给 LLM 配 <strong>grep/搜索工具</strong>（关键词检索比读索引更直接，仍无需向量库）</li><li><strong>语义检索需求</strong>（&quot;想不起来关键词&quot;）→ 重量升级：<strong>RAG 向量检索</strong>（引入向量库 + 索引管线，不再&quot;最简单&quot;）</li></ul><h3 id="增强方向-从-依赖自觉-到-工程兜底" tabindex="-1">增强方向：从&quot;依赖自觉&quot;到&quot;工程兜底&quot; <a class="header-anchor" href="#增强方向-从-依赖自觉-到-工程兜底" aria-label="Permalink to &quot;增强方向：从&quot;依赖自觉&quot;到&quot;工程兜底&quot;&quot;">​</a></h3><p>如果可靠性要求高，把&quot;读知识库&quot;从 LLM 自觉升级为工程机制（呼应 <a href="/knowledge/ai-agent/harness-engineering/function-calling-upgrade.html">dev-agent-harness 的 L2 思路</a>）：</p><ol><li><strong>工具封装</strong>：把&quot;读知识库&quot;封装成 <code>search_kb</code> / <code>read_kb</code> 工具（function calling），比纯提示词可靠</li><li><strong>hook/gate 兜底</strong>：特定场景强制校验&quot;是否读过知识库&quot;，不读不放行</li><li><strong>晋升机制</strong>：稳定重要的条目从&quot;按需文件&quot;晋升到&quot;常驻索引&quot;（对应 Knowledge Harness 的 candidate → review → promote）</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Claude Code 的记忆系统没有向量库、没有知识图谱、没有记忆评分——靠的是<strong>文件组织约定</strong>：</p><ul><li><strong>人工/自动分工</strong>：规范（CLAUDE.md，团队共享）vs 经验（Auto Memory，个人私有）</li><li><strong>索引常驻 + 内容按需</strong>：用最小的常驻 token 换取全局地图</li><li><strong>200 行法则</strong>：索引小型化，防止注意力稀释</li><li><strong>路径 glob 触发</strong>：rules 按文件路径按需加载，是&quot;按需&quot;的最简单落地形态</li></ul><p>这套模式可以直接复刻成你自己的项目级记忆系统——<strong>索引文件是地图，知识文件是货架，LLM 是拿着地图逛货架的人。地图必须常驻，货架按需打开</strong>。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/ai-agent/prompt-engineering/skills.html">Skill：文件化的提示词工程</a> - 两段式加载的另一落地形态</li><li><a href="/knowledge/ai-agent/harness-engineering/core-concepts.html">Harness Engineering 核心思想</a> - Knowledge Harness：记忆治理的工程化</li><li><a href="/knowledge/ai-agent/app-architecture.html">AI 应用架构模式</a> - 长期记忆在应用架构中的位置</li></ul>`,50)])])}const c=a(i,[["render",o]]);export{g as __pageData,c as default};
